phonics.team-build.grain":6,"mock.v6.phonics.team-build.plain":6,"mock.v6.phonics.team-build.cloak":6,"mock.v6.phonics.team-build.coast":6,"mock.v6.phonics.team-build.roast":6,"mock.v6.phonics.team-build.boast":6,"mock.v6.phonics.team-build.clean":6,"mock.v6.phonics.team-build.steep":6}'::jsonb bands,'{"sound_awareness":[{"operation":"compare_initial_sounds","requires":"Compare the initial sounds of recorded familiar words."},{"operation":"map_initial_sound","requires":"Isolate an initial sound and select its letter."},{"operation":"compare_rimes","requires":"Compare the vowel and ending together to find a spoken rhyme."},{"operation":"compare_medial_vowels","requires":"Ignore the consonants and compare the internal vowel of spoken words."},{"operation":"blend_three_phonemes","requires":"Hold and blend three separately recorded phonemes."},{"operation":"manipulate_phoneme","requires":"Add, delete or substitute a phoneme and identify the changed word."}],"phonics":[{"operation":"recognize_familiar_word","requires":"Match one short recorded familiar word to print."},{"operation":"decode_cvc","requires":"Discriminate a complete printed CVC word against other CVC words."},{"operation":"encode_cvc","requires":"Construct all three ordered graphemes of a dictated CVC word."},{"operation":"encode_consonant_blend","requires":"Construct four or more ordered phonemes, including a consonant blend."},{"operation":"decode_split_vowel","requires":"Decode a split-vowel word against its real short-vowel twin."},{"operation":"encode_vowel_team","requires":"Choose a vowel-team grapheme and construct a three-phoneme word; reject spare tiles."},{"operation":"encode_blend_and_vowel_team","requires":"Construct four or more phonemes with both a consonant blend and a vowel team; reject spare tiles."}],"print":[{"operation":"recognize_letter_name","requires":"Match a recorded letter name to its printed glyph."},{"operation":"match_letter_case","requires":"Relate capital and lowercase forms of one letter."},{"operation":"locate_letter_in_word","requires":"Locate the first or last letter within a complete printed word."},{"operation":"locate_word_in_sentence","requires":"Use word boundaries to locate a word within a complete sentence."},{"operation":"navigate_connected_print","requires":"Navigate across a line or sentence boundary, or distinguish multiple complete sentences."}],"vocabulary":[{"operation":"recognize_object_category","requires":"Recognize a familiar word against a picture from another broad category."},{"operation":"discriminate_related_objects","requires":"Distinguish a familiar word from pictures in the same semantic category."},{"operation":"relate_word_meanings","requires":"Relate individual words by synonym or antonym meaning."},{"operation":"interpret_one_context","requires":"Use one occurrence of a word to select its contextual sense."},{"operation":"apply_affix_contrast","requires":"Apply an affix in context against competing forms of the same root."},{"operation":"resolve_competing_contexts","requires":"Resolve a repeated word against another correctly used occurrence or competing true sense."}],"listening":[{"operation":"recognize_spoken_word","requires":"Identify one recorded familiar word."},{"operation":"find_spoken_referent","requires":"Identify the referent within a short recorded sentence."},{"operation":"retrieve_spoken_detail","requires":"Retrieve one explicit detail from a short recording."},{"operation":"resolve_spoken_temporal_links","requires":"Combine two before/after links when the order of mention conflicts with the actual event order."},{"operation":"integrate_spoken_topic_against_details","requires":"Integrate at least two functions or stages; reject two true but incomplete main-idea alternatives."},{"operation":"infer_spoken_lesson","requires":"Infer a general lesson from an unstated mistake-and-repair relationship."},{"operation":"integrate_spoken_episodes","requires":"Find one transferable lesson across two different episodes; reject true lessons fitting only one."}],"language":[{"operation":"recognize_action","requires":"Distinguish an action word from an object word using a picture and recordings."},{"operation":"discriminate_actions","requires":"Distinguish the pictured action from other actions."},{"operation":"classify_word_form","requires":"Identify a word class or plural form without sentence-level reasoning."},{"operation":"understand_one_clause","requires":"Interpret the roles or action in one complete clause."},{"operation":"link_two_clauses","requires":"Combine a causal clause or a pronoun with its referent across clauses."},{"operation":"preserve_scope","requires":"Preserve a quantified, negative or temporal relationship while comparing restatements."}],"reading":[{"operation":"recognize_pictured_word","requires":"Match a picture to one printed word with a distinct initial."},{"operation":"decode_pictured_cvc","requires":"Read the full CVC word against close printed alternatives."},{"operation":"retrieve_printed_detail","requires":"Independently read a short statement and retrieve an explicit detail."},{"operation":"resolve_printed_temporal_links","requires":"Combine two before/after links when the order of mention conflicts with the actual event order."},{"operation":"integrate_printed_topic_against_details","requires":"Integrate at least two functions or stages; reject two true but incomplete main-idea alternatives."},{"operation":"infer_printed_lesson","requires":"Infer a general lesson from an unstated mistake-and-repair relationship."},{"operation":"integrate_printed_episodes","requires":"Find one transferable lesson across two different episodes; reject true lessons fitting only one."}],"writing":[{"operation":"capitalize_name","requires":"Recognize the conventional capitalized form of a supplied name."},{"operation":"capitalize_sentence","requires":"Apply initial capitalisation to a complete sentence."},{"operation":"construct_sentence","requires":"Order words or distinguish a complete simple thought from fragments."},{"operation":"separate_two_thoughts","requires":"Locate the boundary between two simple complete thoughts."},{"operation":"organize_three_events","requires":"Arrange three complete sentences by their prerequisite event relationships."},{"operation":"edit_clause_or_paragraph","requires":"Retain a dependent clause with its main clause, or reject a true but irrelevant paragraph detail."}]}'::jsonb ladders),
classified as (select source.*,case when bands?(s->>'id') then (bands->>(s->>'id'))::integer else null end band,ladders from source cross join route),
snapshots as (select item,s||jsonb_build_object('contentVersion','literacy-mock-v7','adaptiveAreaVersion','areas-v3','adaptiveAreaBand',band,'adaptiveMixedEligible',band is not null,'adaptiveDemand',case when band is null then 'null'::jsonb else ladders->(s->>'domainId')->band end) snapshot from classified)
insert into literacy_mock_incoming select jsonb_set(item,'{itemSnapshot}',snapshot) from snapshots;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v6')<>9138 or (select count(*) from literacy_mock_incoming)<>9138 then raise exception 'Incomplete V7 publication'; end if;
 if exists(select 1 from literacy_mock_incoming incoming join public.literacy_mock_items old on old.id=incoming.item->>'id' and old.content_version='literacy-mock-v7' where old.item is distinct from incoming.item) then raise exception 'Cannot rewrite immutable V7 publication'; end if;
end; $$;
insert into public.literacy_mock_items(id,content_version,item) select item->>'id','literacy-mock-v7',item from literacy_mock_incoming on conflict(id,content_version) do nothing;
insert into public.literacy_mock_publications(content_version,item_count) values('literacy-mock-v7',9138) on conflict(content_version) do nothing;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v7')<>9138 then raise exception 'V7 publication count mismatch'; end if;
end; $$;
commit;
